enum { ROP_SELECT_UNINTERRUPTED, ROP_SELECT_INTERRUPTIBLE };  /* interrupt */
enum { ROP_SELECT_JIT_OFF, ROP_SELECT_JIT_ON };  /* jit */
enum { ROP_SELECT_UNARY, ROP_SELECT_IMPORT_STAR, ROP_SELECT_STOPITERATION };  /* intrinsic1 */
enum { ROP_SELECT_BINARY, ROP_SELECT_ATTR };  /* intrinsic2 */
enum { ROP_SELECT_NAMED, ROP_SELECT_LOCALS_SCOPE, ROP_SELECT_BUILD_CLASS_SCOPE };  /* name_read */
